#!/usr/bin/env node
// Generates the Swift mirror of the security-bearing constants in
// `contracts/src/bridge/http.ts` so the macOS shell cannot drift from the
// contract. `--check` verifies the generated file matches (CI/DoD mode);
// default rewrites it.
//
// Why this exists (wave-7 FG-2): the shell hardcoded the channel name, the
// forbidden-header list, and the failure-reason/status mapping, kept in sync by
// hand. A rename in the contract compiled fine and silently broke the shell at
// runtime — and a wrong forbidden-header list is a credential-forgery hole, not
// a cosmetic bug. The prototype's own bridge.json -> Bridge.generated.swift flow
// is the precedent for fixing it by generation.
//
// Extraction is deliberately regex-grade over COMMENT-STRIPPED source, matching
// four specific declarations rather than parsing TypeScript. It fails loudly on
// anything it does not recognise, and cross-checks the reason union against the
// status map, so a silent partial generation is not possible.
import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join } from "node:path";

const ROOT = new URL("..", import.meta.url).pathname;
const SOURCE_REL = "contracts/src/bridge/http.ts";
const OUT_REL = "shell/Sources/OmiShell/BridgeHttpContract.generated.swift";

// The macOS shell prototype lives in the tracker repo. Resolve it the way
// build-shell.sh resolves core: an env override, else the sibling checkout.
const SHELL_DIR =
  process.env.OMI_MACOS_SHELL_DIR ??
  join(ROOT, "../../omi-frontend-unification-and-microapps-project-tracker/prototypes/macos-webview-shell");

const check = process.argv.includes("--check");

/** Strip block and line comments so quoted words in prose cannot be mistaken for values. */
function stripComments(src) {
  return src.replace(/\/\*[\s\S]*?\*\//g, "").replace(/^[ \t]*\/\/.*$/gm, "");
}

function fail(msg) {
  console.error(`gen-bridge-swift: ${msg}`);
  console.error(`  source: ${SOURCE_REL}`);
  process.exit(1);
}

const src = stripComments(readFileSync(join(ROOT, SOURCE_REL), "utf8"));

// 1. export const BRIDGE_HTTP_CHANNEL = "omiHttp";
const channelMatch = src.match(/export const BRIDGE_HTTP_CHANNEL\s*=\s*"([^"]+)"/);
if (!channelMatch) fail("could not extract BRIDGE_HTTP_CHANNEL");
const channel = channelMatch[1];

// 2. export const BRIDGE_HTTP_FORBIDDEN_HEADERS = [...] as const;
const headersMatch = src.match(/export const BRIDGE_HTTP_FORBIDDEN_HEADERS[^=]*=\s*\[([^\]]*)\]/);
if (!headersMatch) fail("could not extract BRIDGE_HTTP_FORBIDDEN_HEADERS");
const headers = [...headersMatch[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
if (headers.length === 0) fail("BRIDGE_HTTP_FORBIDDEN_HEADERS extracted as empty — refusing to weaken the shell");

// 3. export type BridgeHttpFailureReason = "a" | "b" | ...;
const reasonMatch = src.match(/export type BridgeHttpFailureReason\s*=([^;]*);/);
if (!reasonMatch) fail("could not extract BridgeHttpFailureReason");
const reasons = [...reasonMatch[1].matchAll(/"([^"]+)"/g)].map((m) => m[1]);
if (reasons.length === 0) fail("BridgeHttpFailureReason extracted as empty");

// 4. export const BRIDGE_HTTP_FAILURE_STATUS ... = { key: 503, "quoted-key": 401, };
const statusMatch = src.match(/export const BRIDGE_HTTP_FAILURE_STATUS[^=]*=\s*\{([^}]*)\}/);
if (!statusMatch) fail("could not extract BRIDGE_HTTP_FAILURE_STATUS");
const statuses = new Map(
  [...statusMatch[1].matchAll(/(?:"([^"]+)"|([A-Za-z_$][\w$]*))\s*:\s*(\d+)/g)].map((m) => [m[1] ?? m[2], Number(m[3])]),
);
if (statuses.size === 0) fail("BRIDGE_HTTP_FAILURE_STATUS extracted as empty");

// Cross-check: a reason with no status (or a status with no reason) means the
// contract and the generated Swift would disagree about the taxonomy.
const missingStatus = reasons.filter((r) => !statuses.has(r));
const orphanStatus = [...statuses.keys()].filter((k) => !reasons.includes(k));
if (missingStatus.length) fail(`reasons with no status mapping: ${missingStatus.join(", ")}`);
if (orphanStatus.length) fail(`status entries with no matching reason: ${orphanStatus.join(", ")}`);

const swiftEnumCase = (reason) => reason.replace(/-([a-z])/g, (_, c) => c.toUpperCase());

const lines = [
  `// GENERATED by core/scripts/gen-bridge-swift.mjs from ${SOURCE_REL} — do not edit by hand.`,
  `// Run \`node scripts/gen-bridge-swift.mjs\` in core/ after changing that contract;`,
  `// \`--check\` fails on drift and is part of the core Definition of Done.`,
  "",
  "enum BridgeHttpContract {",
  `  /// BRIDGE_HTTP_CHANNEL — the message-handler name the surface feature-detects.`,
  `  static let channel = "${channel}"`,
  "",
  "  /// BRIDGE_HTTP_FORBIDDEN_HEADERS — stripped from caller headers, case-insensitively,",
  "  /// BEFORE the shell adds its own credential. Enforced, never trusted.",
  "  static let forbiddenHeaders: Set<String> = [",
  ...headers.map((h) => `    "${h}",`),
  "  ]",
  "",
  "  /// BridgeHttpFailureReason — the only reasons a shell may report.",
  "  enum FailureReason: String {",
  ...reasons.map((r) => `    case ${swiftEnumCase(r)} = "${r}"`),
  "  }",
  "",
  "  /// BRIDGE_HTTP_FAILURE_STATUS — the synthetic status the web binding maps each",
  "  /// reason onto, so `classifyStatus` stays the one place statuses become taxonomy.",
  "  static func syntheticStatus(for reason: FailureReason) -> Int {",
  "    switch reason {",
  ...reasons.map((r) => `    case .${swiftEnumCase(r)}: return ${statuses.get(r)}`),
  "    }",
  "  }",
  "}",
  "",
];
const content = lines.join("\n");

if (!existsSync(SHELL_DIR)) {
  // Absence is not drift: core must be verifiable without the tracker checkout.
  console.log(
    `bridge swift: SKIPPED — macOS shell prototype not found at ${OUT_REL} host dir (set OMI_MACOS_SHELL_DIR to override).`,
  );
  process.exit(0);
}

const outAbs = join(SHELL_DIR, OUT_REL);
let current = null;
try {
  current = readFileSync(outAbs, "utf8");
} catch {
  current = null;
}

if (check) {
  if (current !== content) {
    console.error(
      `bridge swift drift: ${OUT_REL} — run \`node scripts/gen-bridge-swift.mjs\` in core/`,
    );
    process.exit(1);
  }
  console.log(`bridge swift in sync (channel=${channel}, ${headers.length} forbidden headers, ${reasons.length} reasons).`);
} else {
  if (current !== content) {
    writeFileSync(outAbs, content);
    console.log(`wrote ${OUT_REL}`);
  } else {
    console.log(`bridge swift already current`);
  }
  console.log(`bridge swift generated (channel=${channel}, ${headers.length} forbidden headers, ${reasons.length} reasons).`);
}
